#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

if [[ ! -d "supabase/migrations" ]]; then
  warn "Run this from the repo root (supabase/migrations/ not found here)."
  exit 1
fi

banner "Supabase setup for Silbador persistence"

# ── Stage 1: create the project ────────────────────────────────────────────
stage "Create the Supabase project"
say "If you don't have a Supabase account yet, sign up first."
open_url "https://supabase.com/dashboard/projects"
step "Click 'New project', pick an org, name it (e.g. silbador), set a strong"
step "database password (save it somewhere - you won't need it for this"
step "wizard, but you'll want it if you ever need direct psql access), pick a"
step "region, and create it. Wait for provisioning to finish (~2 min)."
pause "Press Enter once the project is up and you're on its dashboard."

# ── Stage 2: security-relevant Data API settings ───────────────────────────
stage "Configure Data API settings"
say "The spec requires these three switches (Project Settings -> Data API,"
say "sometimes labelled just 'API' or 'API Settings' - Supabase has renamed"
say "this tab a few times):"
open_url "https://supabase.com/dashboard/project/_/settings/api"
step "Enable Data API: ON"
step "Automatically expose new tables: OFF (we expose tables on purpose, via RLS)"
step "Enable automatic RLS: ON (safety net for any future table)"
confirm "Set all three as above?" || warn "Fix these before going further - RLS is the only access control here."

# ── Stage 3: capture client + test credentials ─────────────────────────────
stage "Copy API credentials"
say "Same page (Project Settings -> API Keys). Supabase renamed these keys:"
say "'Publishable key' replaced 'anon', 'Secret key' replaced 'service_role'."
say "supabase-js treats them as drop-in replacements, so either generation"
say "works - if your project still shows the old names (or a 'Legacy API"
say "keys' toggle), use anon/service_role instead."
step "Copy the Project URL."
ask VITE_SUPABASE_URL "Project URL:"
step "Copy the Publishable key (or 'anon' if that's what you see) - safe to"
step "ship to the browser."
ask VITE_SUPABASE_ANON_KEY "Publishable / anon key:"
step "Copy the Secret key (or 'service_role'). This is ONLY for running the"
step "local integration test suite (src/data/__tests__/songs.test.ts) - it is"
step "never used by the app itself and must never be shipped to a browser."
ask_secret SUPABASE_TEST_SERVICE_ROLE_KEY "Secret / service_role key (used by tests only):"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
write_env SUPABASE_TEST_SERVICE_ROLE_KEY "$SUPABASE_TEST_SERVICE_ROLE_KEY"
note "These went into $ENV_FILE, which is gitignored - never commit it."

# ── Stage 4: link the CLI and push the migration ───────────────────────────
stage "Apply the schema (Supabase CLI)"
say "This pushes supabase/migrations/0001_init.sql (profiles/songs/favorites,"
say "triggers, RLS) to the project you just created."
if ! command -v supabase >/dev/null 2>&1; then
  warn "Supabase CLI not found."
  open_url "https://supabase.com/docs/guides/local-development/cli/getting-started#installing-the-supabase-cli"
  step "Install it (e.g. 'brew install supabase/tap/supabase' on macOS), then come back."
  pause "Press Enter once 'supabase --version' works."
fi
step "Find your project ref in the dashboard URL: https://supabase.com/dashboard/project/<ref>"
ask SUPABASE_PROJECT_REF "Project ref:"
say "About to run, from $(pwd):"
note "  supabase login"
note "  supabase link --project-ref $SUPABASE_PROJECT_REF"
note "  supabase db push"
if confirm "Run these three commands now?"; then
  supabase login
  supabase link --project-ref "$SUPABASE_PROJECT_REF"
  supabase db push
else
  SKIPPED+=("supabase login && supabase link --project-ref $SUPABASE_PROJECT_REF && supabase db push")
  warn "Skipped - run those three commands yourself before using the app."
fi

# ── Stage 5: promote yourself to admin ──────────────────────────────────────
stage "Create your account and become the admin"
say "The 'admin' role can mark songs public; it's assigned by hand once, in SQL,"
say "per supabase/README.md - there is no self-serve signup path to it."
step "Sign in to the app once you have a UI (magic link), OR create a user now"
step "from the dashboard's Authentication -> Users -> Add user."
open_url "https://supabase.com/dashboard/project/_/auth/users"
step "Copy that user's UUID from the Users table."
ask SILBADOR_ADMIN_USER_ID "Your user's UUID:"
open_url "https://supabase.com/dashboard/project/_/sql/new"
say "Paste and run this in the SQL editor that just opened:"
note "  update profiles set role = 'admin' where id = '$SILBADOR_ADMIN_USER_ID';"
pause "Press Enter once you've run it."

# ── Stage 6: verify ─────────────────────────────────────────────────────────
stage "Verify"
say "With the env vars above in place, the integration suite (previously"
say "skipped) should now run for real:"
note "  npm run test"
say "It provisions and tears down its own ephemeral test users each run via"
say "the service_role key, so it won't touch the admin user you just created."
pause "Press Enter to finish."

finish
